//! 文件窗口那几格设计令牌的名单（契约 `filewin_contract::THEME_TOKENS`）的生成物：`src/frontend/ui/generated/filewin-theme-tokens.ts`。
//!
//! 值取契约那一份本身，界面 import 生成物，不另写一份字面量。`npm run gen:types`（= `cargo test --lib export_bindings`）重写它；
//! 门禁 `generated` 格（`generated-drift.sh`）盖住「改了名单不重跑生成」。

use filewin_contract::THEME_TOKENS;

/// 生成物的头。`generated-boundary-guard.vitest.ts` 认两样：「谁生成的」那一行（本文件挂在 `theme.rs` 底下）＋「不许手改」那句话。
const HEADER: &str = "\
// 本文件由 `src/frontend/filewin/src/theme.rs` 的
// `export_bindings_filewin_theme_tokens` 生成（`npm run gen:types`）。Do not edit this file manually.
";

fn render_theme_tokens() -> String {
    let mut s = String::from(HEADER);
    s.push_str(
        "\n/** 文件窗口要的那几格设计令牌（`filewin_contract::THEME_TOKENS`）：开窗那一刻按它读 `:root` 的计算值、原样交给壳。 */\nexport const THEME_TOKENS = [\n",
    );
    for t in THEME_TOKENS {
        let lit = serde_json::to_string(t).expect("字符串序列化不会失败");
        s.push_str(&format!("  {lit},\n"));
    }
    s.push_str("] as const;\n");
    s
}

/// 生成 `src/frontend/ui/generated/filewin-theme-tokens.ts`。
#[test]
fn export_bindings_filewin_theme_tokens() {
    let out =
        guard_core::addr::repo_root().join("src/frontend/ui/generated/filewin-theme-tokens.ts");
    std::fs::write(&out, render_theme_tokens())
        .unwrap_or_else(|e| panic!("写不进 {}：{e}", out.display()));
}
